from statistics import mean, stdev
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd


def plot_summary(df_sovrastima, df_sottostima):
    ticks_sovrastima = df_sovrastima['Interval']
    freqs_sovrastima = df_sovrastima['Count']
    avg_sovrastima = df_sovrastima['Avg']
    deviation_sovrastima = df_sovrastima['StDev']

    ticks_sottostima = df_sottostima['Interval']
    freqs_sottostima = df_sottostima['Count']
    avg_sottostima = df_sottostima['Avg']
    deviation_sottostima = df_sottostima['StDev']

    fig, (ax1, ax2) = plt.subplots(2, 1, sharex=True, gridspec_kw={'hspace': 0})
    # make a plot
    ax1.plot(ticks_sovrastima, avg_sovrastima, color="red")
    ax1.fill_between(ticks_sovrastima, avg_sovrastima - deviation_sovrastima, avg_sovrastima + deviation_sovrastima, color="red", alpha=0.3)
    # set x-axis label
    ax1.set_xlabel("T[K]", fontsize=14)
    # set y-axis label
    ax1.set_ylabel("Ratio", color="red", fontsize=14)

    ax11 = ax1.twinx()
    # make a plot with different y-axis using second axis object
    ax11.bar(ticks_sovrastima, freqs_sovrastima, alpha=0.3, width=20, color='royalblue')
    ax11.set_ylabel("Frequency", alpha=0.5, color="royalblue", fontsize=14)

    # Sottostima

    # make a plot
    ax2.plot(ticks_sottostima, avg_sottostima, color="red")
    ax2.fill_between(ticks_sottostima, avg_sottostima - deviation_sottostima, avg_sottostima + deviation_sottostima, color="red", alpha=0.3)

    # set x-axis label
    ax2.set_xlabel("T[K]", fontsize=14)
    # set y-axis label
    ax2.set_ylabel("Ratio", color="red", fontsize=14)

    ax22 = ax2.twinx()
    # make a plot with different y-axis using second axis object
    ax22.bar(ticks_sottostima, freqs_sottostima, alpha=0.3, width=20, color='royalblue')
    ax22.set_ylabel("Frequency", alpha=0.5, color="royalblue", fontsize=14)

    ax2.invert_yaxis()
    ax22.invert_yaxis()

    plt.show()
    plt.close()


